package org.example.otppager

import org.bouncycastle.crypto.digests.SHA3Digest
import java.security.SecureRandom

/**
 * Where pad bytes come from (pairing protocol v11, docs/PAD_PROTOCOL.md):
 *  - each phone runs its own generator, seeded with extra hardware noise when available;
 *  - every generated byte passes continuous health tests before it is used;
 *  - the pad is the XOR of both phones' full-length streams, so it is at least as unpredictable
 *    as the better of the two generators. There is no stretching of a short seed.
 * A phone's generator is still a cryptographic DRBG: this is as close to a true one-time pad as
 * phone hardware allows, not a certified true-random source.
 */
internal object PadEntropy {
    class HealthFailure(message: String) : IllegalStateException(message)

    /**
     * Continuous tests on generator output, in the style of NIST SP 800-90B §4.4 for an 8-bit
     * full-entropy source, with cutoffs set for a false-alarm chance below about 2^-30 per pad:
     *  - repetition count: the same byte 8 times in a row;
     *  - adaptive proportion: one byte value 18 or more times in a 512-byte window;
     *  - repeated 32-byte block (the classic stuck-generator test).
     */
    class OutputMonitor {
        private var last = -1; private var run = 0
        private var windowFirst = -1; private var windowCount = 0; private var windowSeen = 0
        private var previousBlock: ByteArray? = null
        private val block = ByteArray(32); private var blockFill = 0
        fun check(bytes: ByteArray, from: Int = 0, to: Int = bytes.size) {
            for (i in from until to) {
                val b = bytes[i].toInt() and 255
                if (b == last) { if (++run >= REPEAT_CUTOFF) throw HealthFailure("Random generator stuck (repetition test)") } else { last = b; run = 1 }
                if (windowSeen == 0) { windowFirst = b; windowCount = 1 } else if (b == windowFirst && ++windowCount >= PROPORTION_CUTOFF)
                    throw HealthFailure("Random generator biased (proportion test)")
                if (++windowSeen == WINDOW) windowSeen = 0
                block[blockFill++] = bytes[i]
                if (blockFill == block.size) {
                    if (previousBlock?.contentEquals(block) == true) throw HealthFailure("Random generator repeated a block")
                    previousBlock = (previousBlock ?: ByteArray(32)).also { block.copyInto(it) }; blockFill = 0
                }
            }
        }
        companion object { const val REPEAT_CUTOFF = 8; const val PROPORTION_CUTOFF = 18; const val WINDOW = 512 }
    }

    /**
     * SP 800-90B §4.4 health tests on raw noise (the low byte of each 16-bit audio sample),
     * assuming only 1 bit of min-entropy per sample: repetition cutoff 41, adaptive proportion
     * cutoff 410 in 512-sample windows. A silent, muted or stuck microphone fails.
     */
    fun noiseHealthy(lowBytes: ByteArray): Boolean {
        if (lowBytes.size < MIN_NOISE_SAMPLES) return false
        var last = -1; var run = 0; var first = -1; var count = 0; var seen = 0
        for (value in lowBytes) {
            val b = value.toInt() and 255
            if (b == last) { if (++run >= 41) return false } else { last = b; run = 1 }
            if (seen == 0) { first = b; count = 1 } else if (b == first && ++count >= 410) return false
            if (++seen == 512) seen = 0
        }
        return true
    }
    /** At 1 bit per sample this is 8,192 bits, far more than the 512 kept after conditioning. */
    const val MIN_NOISE_SAMPLES = 8192

    /** SHA3-512 conditioning of raw noise to a 64-byte seed (SP 800-90B §3.1.5 vetted conditioner). */
    fun condition(raw: ByteArray): ByteArray {
        val digest = SHA3Digest(512); digest.update(raw, 0, raw.size)
        return ByteArray(64).also { digest.doFinal(it, 0) }
    }

    /** A fresh generator for one pairing. [noiseSeed] supplements (never replaces) its own seeding. */
    fun generator(noiseSeed: ByteArray?): SecureRandom = SecureRandom().also { random ->
        if (noiseSeed != null) { require(noiseSeed.size == 64); random.setSeed(noiseSeed) }
        random.nextBytes(ByteArray(32)) // Force seeding now, before any pad byte is drawn.
    }
}
